        public object Process_TableModel()
        {
            var new_ModelConfigID = 0;
            var sql_DataSet_DataAdapter = new SqlDataAdapter();
            var FMM_CalcConfig_Config_DT = new DataTable();
            var dbConnApp = BRApi.Database.CreateApplicationDbConnInfo(si);
            using (var connection = new SqlConnection(dbConnApp.ConnectionString))
            {
                connection.Open();
                var sql_FMM_Get_DataSets = new FMM_ConfigUI_Assembly.SQL_FMM_Get_DataSets(si, connection);
                Seed_Temp_Tables_for_Calcs();

                var Proc_FinModel_Sql = @"
                    Select Sequence,Calc_Src_Type,Calc_Src_Item,Table_Calc_Expression,
					Table_Join_Expression,Table_Filter_Expression,Calc_Plan_Units,Acct,View,IC,
					Flow,UD1,UD2,UD3,UD4,UD5,UD6,UD7,
					UD8,OS_Time_Filter,OS_Conditional_Filter
                    FROM FMM_CalcConfig_Config calc
                    JOIN FMM_Src_Cell Src
                    ON calc.CalcConfigID = Src.CalcConfigID
					AND calc.ModelConfigID = Src.ModelConfigID
					JOIN FMM_Cell Dest
                    ON calc.CalcConfigID = Dest.CalcConfigID
					AND calc.ModelConfigID = Dest.ModelConfigID
                    WHERE ModelConfigID = @ModelConfigID
					AND Src.Calc_Src_ID_Order = 0
					AND Src.Calc_Src_Type IN ('Proportional Time','Allocation')
					ORDER By Sequence";

                var parameters = new SqlParameter[]
                {
                    new SqlParameter("@ModelConfigID", SqlDbType.Int) { Value = new_ModelConfigID }
                };

                // Fetch rows into a DataTable
                sql_FMM_Get_DataSets.Fill_get_FMM_DataTable(si, sql_DataSet_DataAdapter, FMM_CalcConfig_Config_DT, Proc_FinModel_Sql, parameters);

                // Process rows dynamically based on Calc_Src_Type
                foreach (DataRow row in FMM_CalcConfig_Config_DT.Rows)
                {
                    string calcSrcType = row["Calc_Src_Type"].ToString();
                    ProcessCalculationType(calcSrcType, row);
                }
                // Loop through results
            }
            return "Calculations Completed";
        }

