        #endregion

        private void find_SetApprovalIDs(ref int ApprID, ref int Appr_Step_ID)
        {
            var wfInitInfo = BRApi.Workflow.General.GetUserWorkflowInitInfo(si);
            var wfUnitInfo = wfInitInfo.GetSelectedWorkflowUnitInfo();

            //				var wfScenario = wfUnitInfo.ScenarioName;
            //				var wfName = wfUnitInfo.WorkflowName;
            var wfProfile = wfUnitInfo.ProfileName;
            //				var other = wfUnitInfo.WfUnitPk;
            //				var cubeinfo = BRApi.Workflow.Metadata.GetCubeRootInfo(si, wfUnitInfo.WfUnitPk.ProfileKey, false);
            //				var cubeName = cubeinfo.CubeRootProfile.CubeName;


            var FMM_ApprConfigoval_Step_Config_DT = new DataTable();

            var dbConnApp = BRApi.Database.CreateApplicationDbConnInfo(si);
            using (var connection = new SqlConnection(dbConnApp.ConnectionString))
            {
                var sql_Adapter_FMM_ApprConfigoval_Step_Config = new SQL_Adapter_FMM_ApprConfigoval_Step_Config(si, connection);
                var sqlDataAdapter = new SqlDataAdapter();

                // Fill DataTable for Approval_Step_Config
                // Possibly... need to have cube information to determine if we're within the right cube
                string selectQuery = @"
	                    SELECT ApprID, Appr_Step_ID, WFProfile_Step 
	                    FROM FMM_ApprConfigoval_Step_Config
	                    WHERE WFProfile_Step = @Profile
						OR @Profile like WFProfile_Step";

                var parameters = new SqlParameter[]
                {
                        new SqlParameter("@Profile", SqlDbType.NVarChar, 100) { Value = wfProfile }
                };

                sql_Adapter_FMM_ApprConfigoval_Step_Config.Fill_FMM_ApprConfigoval_Step_Config_DataTable(si, sqlDataAdapter, FMM_ApprConfigoval_Step_Config_DT, selectQuery, parameters);

                if (FMM_ApprConfigoval_Step_Config_DT.Rows.Count > 0)
                {
                    //Find exact matches first
                    var exactMatches = FMM_ApprConfigoval_Step_Config_DT.Select($"WFProfile_Step = '{wfProfile}'");

                    //if no matched rows were found, get the top row of the data table as a fuzzy match
                    if (exactMatches.Length != 0)
                    {
                        ApprID = Convert.ToInt32(exactMatches[0]["ApprID"]);
                        Appr_Step_ID = Convert.ToInt32(exactMatches[0]["Appr_Step_ID"]);
                    }
                    else
                    {
                        var likeMatch = FMM_ApprConfigoval_Step_Config_DT.Rows[0];

                        ApprID = Convert.ToInt32(likeMatch["ApprID"]);
                        Appr_Step_ID = Convert.ToInt32(likeMatch["Appr_Step_ID"]);
                    }
                }
                else
                {
                    BRApi.ErrorLog.LogMessage(si, "No matching approval steps found");
                }

            }


            //				ApprID = 2;
            //				Appr_Step_ID = 0;
        }

        #endregion
    }
}

﻿using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Globalization;
using System.IO;
using System.Linq;
using Microsoft.CSharp;
using OneStream.Finance.Database;
using OneStream.Finance.Engine;
using OneStream.Shared.Common;
using OneStream.Shared.Database;
using OneStream.Shared.Engine;
using OneStream.Shared.Wcf;
using OneStream.Stage.Database;
using OneStream.Stage.Engine;
using static Workspace.OSBuildToolkit.FMM_Shared_Assembly.FMM_RegPlan_Helpers;

namespace Workspace.__WsNamespacePrefix.__WsAssemblyName.BusinessRule.DashboardExtender.FMM_RegPlan_DBExt
{
    public class MainClass
    {
        public object Main(SessionInfo si, BRGlobals globals, object api, DashboardExtenderArgs args)
        {

            string NVPFilter = "FilterVal";
            string NVPSearch = "SearchVal";

            try
            {
                switch (args.FunctionType)
                {
                    case DashboardExtenderFunctionType.LoadDashboard:
                        if (args.FunctionName.XFEqualsIgnoreCase("TestFunction"))
                        {
                            // Implement Load Dashboard logic here.
                            if (args.LoadDashboardTaskInfo.Reason == LoadDashboardReasonType.Initialize && args.LoadDashboardTaskInfo.Action == LoadDashboardActionType.BeforeFirstGetParameters)
                            {
                                var loadDashboardTaskResult = new XFLoadDashboardTaskResult();
                                loadDashboardTaskResult.ChangeCustomSubstVarsInDashboard = false;
                                loadDashboardTaskResult.ModifiedCustomSubstVars = null;
                                return loadDashboardTaskResult;
                            }
                        }
                        break;
                    case DashboardExtenderFunctionType.ComponentSelectionChanged:
                        if (args.FunctionName.XFEqualsIgnoreCase("SetFilterSearchParams"))
                        {
                            // Implement Dashboard Component Selection Changed logic here.
                            var selectionChangedTaskResult = new XFSelectionChangedTaskResult();
                            selectionChangedTaskResult.IsOK = true;
                            selectionChangedTaskResult.ChangeCustomSubstVarsInDashboard = true;

                            string filterVal = args.NameValuePairs.XFGetValue(NVPFilter, string.Empty);
                            string searchVal = args.NameValuePairs.XFGetValue(NVPSearch, string.Empty);

                            //BRApi.ErrorLog.LogMessage(si, $"DE: filter: {filterVal} search: {searchVal}");

                            if (filterVal != string.Empty)
                            {
                                selectionChangedTaskResult.ModifiedCustomSubstVars.Add(FMM_Register_Plan_Helpers.filterIV, filterVal);
                            }
                            if (searchVal != string.Empty)
                            {
                                selectionChangedTaskResult.ModifiedCustomSubstVars.Add(FMM_Register_Plan_Helpers.searchIV, searchVal);
                            }

